 "에이전트와 평소처럼 대화하면, 대화가 끝나고 몇 분 뒤 기억 후보가 여기 와요. 내가 승인한 것만 저장돼요.": "Converse com os agentes como de costume. Alguns minutos depois que a conversa termina, os candidatos a memória chegam aqui. Só o que você aprovar é salvo.",
