 "에이전트(Claude Code·Codex·Gemini CLI)를 연결하면 요청이 라우터를 거쳐 알맞은 모델로 가고, 여기에 요청 수·응답 시간·비용이 나와요.": "Conecte um agente (Claude Code, Codex, Gemini CLI) e as requisições passarão pelo roteador até o modelo certo. Aqui aparecerão o número de requisições, o tempo de resposta e o custo.",
