 "연결하지 못했어요.": "Não foi possível conectar.",
 "이미 연결하는 중이에요.": "Já está conectando.",
 "이 PC에서 찾지 못했어요.": "Não encontrado neste PC.",
 "연결한 에이전트는 이 PC의 Arkism 중계기로 요청을 보내고, 설정 › 에이전트에서 켠 모델 중에서 자동으로 골라 답해요. 각자 로그인은 그대로 써요.": "Os agentes conectados enviam as solicitações para o gateway do Arkism neste PC, que escolhe automaticamente entre os modelos ativados em Configurações › Agentes. Cada agente continua usando o próprio login.",
 "기본 모델이 ‘자동’이 돼요. /model에서 다른 모델도 고를 수 있어요.": "O modelo padrão passa a ser ‘Automático’. Você ainda pode escolher outros modelos com /model.",
