 "아직 서버 검사가 안 된 스킬이라, 스킬 설명이 얼마나 갖춰졌는지와 가져올 때 검사한 결과로 보여줘요.": "Esta skill ainda não passou pela verificação do servidor, então mostramos o quanto a descrição está completa e o que foi verificado na importação.",
 "Arkism 내장 검사(비밀값·원격 실행·삭제 명령·자격 파일·유출·프롬프트 주입, SKILL.md 구성)가 서버의 스킬 폴더를 검사한 결과예요.": "Resultado da verificação integrada do Arkism na pasta da skill no servidor (segredos, execução remota, comandos de exclusão, arquivos de credenciais, vazamento de dados, injeção de prompt, estrutura do SKILL.md).",
