 "질문으로 시험해 보기": "Testar com uma pergunta",
 "질문할 때 더 들어가는 기억": "Memórias adicionadas quando você pergunta",
 "시험할 질문": "Pergunta para testar",
 "8자보다 짧은 질문에는 아무것도 넣지 않아요.": "Nada é adicionado a perguntas com menos de 8 caracteres.",
 "이 질문에는 더 들어가는 기억이 없어요.": "Nenhuma memória extra seria adicionada a esta pergunta.",
 "실제 검색을 한 번 해요. 이 검색도 서버의 검색 기록에 남아요.": "Faz uma busca de verdade, que também fica no histórico de buscas do servidor.",
