 "세션 시작 때 들어가는 기억 미리보기": "Prévia da memória injetada no início da sessão",
 "저장소 밖 폴더 (공용 기억만)": "Pasta fora de um repositório (somente memórias compartilhadas)",
 "저장소에 작업 계약 파일이 있으면 관련 기억(최대 6개)이 따로 붙고, 그만큼 목차 자리가 줄어요. 계약 파일은 그 PC에서만 읽을 수 있어 여기선 빠져요.": "Se o repositório tiver um arquivo de contrato de tarefa, as memórias relacionadas (até 6) são adicionadas à parte e o índice perde esse espaço. Só aquele PC consegue ler o arquivo de contrato, então ele não aparece aqui.",
 "예: 배포 전에 무엇을 확인해야 해?": "Ex.: o que devo verificar antes de publicar?",
 "자 · 대화 시작 + 질문": "caracteres · início da conversa + perguntas",
 "찾아보기": "Buscar",
 "이 계정은 개인정보를 지울 수 없어요.": "Esta conta não pode apagar dados pessoais.",
 "다른 지우기 요청이 진행 중이거나 그새 바뀌었어요. 잠시 뒤 다시 시도하세요.": "Outro pedido de exclusão está em andamento, ou algo mudou nesse meio-tempo. Tente de novo daqui a pouco.",
 "이미 지워졌거나 찾을 수 없어요.": "Já foi apagado ou não foi encontrado.",
