 "만료일을 지웠어요. 계속 써요.": "Data de expiração removida. Ela continua em uso.",
 "그새 바뀐 기억이에요. 다시 선택해 주세요.": "Esta memória mudou nesse meio-tempo. Selecione-a de novo.",
 "이 계정은 만료일을 바꿀 수 없어요.": "Esta conta não pode alterar datas de expiração.",
 "만료일": "Data de expiração",
 "이 시각이 지나면 불러오지도, 검색되지도 않아요.": "Depois desse momento, ela não é mais recuperada nem aparece nas buscas.",
 "정해 두면 그 뒤로는 에이전트가 이 기억을 쓰지 않아요.": "Se você definir uma, os agentes deixam de usar esta memória depois dessa data.",
