 "만료일 지우기": "Remover expiração",
 "개인정보 지우기": "Apagar dados pessoais",
 "이 기억과 근거가 된 원본 기록을 영구히 지워요. 같은 원본에서 나온 다른 기억도 함께 지워져요.": "Apaga permanentemente esta memória e os registros originais que serviram de base. Outras memórias vindas das mesmas fontes também são apagadas.",
 "영구 삭제": "Apagar permanentemente",
 "사람 이름이나 메일 주소처럼 지우고 싶은 말을 넣으면, 그 말이 들어간 기억과 원본 기록을 모두 찾아 영구히 지워요. 먼저 몇 개인지 보여 드려요.": "Digite o que você quer apagar, como o nome de uma pessoa ou um endereço de e-mail. O Arkism encontra todas as memórias e registros originais que contêm esse texto e os apaga permanentemente. Antes, mostramos quantos são.",
 "지울 말 (이름·메일 주소 등)": "Texto a apagar (nome, e-mail etc.)",
 "예: 홍길동, name@example.com": "Ex.: Maria Silva, nome@exemplo.com",
 "너무 많아 일부만 셌어요. 지운 뒤 다시 찾아보세요.": "São muitos para contar todos. Busque de novo depois de apagar.",
 "조금 짧게 입력하세요.": "Digite um texto um pouco mais curto.",
 "두 글자 이상 입력하세요.": "Digite pelo menos dois caracteres.",
 "이 계정은 기억과 원본 기록을 찾을 수 없어요.": "Esta conta não pode buscar memórias nem registros originais.",
 "찾지 못했어요. 연결을 확인하고 다시 시도하세요.": "Não foi possível buscar. Verifique a conexão e tente de novo.",
