 "서버 연결은 Arkism 앱에서만 돼요.": "A conexão com servidores só funciona no app Arkism.",
 "접속 토큰": "Token de acesso",
 "서버 관리자에게 받은 Arkism 접속 토큰. 이 탭을 닫으면 지워져요": "O token de acesso do Arkism que o administrador do servidor enviou. Ele é apagado quando você fecha esta aba",
 "자세히 (워크스페이스·프로젝트)": "Detalhes (workspace · projeto)",
