 "비우면 default": "Em branco usa default",
 "접속 토큰을 넣어 주세요. 띄어쓰기 없이 한 줄이어야 해요.": "Informe o token de acesso: uma linha, sem espaços.",
 "Arkism 서버에 로그인": "Entrar no servidor do Arkism",
 "서버 관리자에게 받은 접속 토큰을 붙여 넣으세요. 토큰은 이 브라우저 탭에만 두고, 탭을 닫으면 지워져요.": "Cole o token de acesso que o administrador do servidor enviou. O token fica só nesta aba do navegador e é apagado quando você fecha a aba.",
 "주소를 확인하세요. user@서버주소 또는 user@서버주소:포트 처럼 적어요.": "Verifique o endereço. Escreva assim: usuario@servidor ou usuario@servidor:porta.",
 "이 PC에서 ssh 프로그램을 찾지 못했어요. OpenSSH(또는 Git for Windows)를 설치해 주세요.": "Não foi possível encontrar o ssh neste PC. Instale o OpenSSH (ou o Git for Windows).",
 "SSH 로그인이 거부됐어요. 이 PC에서 ‘ssh 주소’가 비밀번호 없이(SSH 키로) 되는지 확인하세요.": "O login por SSH foi recusado. Verifique se ‘ssh endereço’ funciona neste PC sem senha (com chave SSH).",
 "서버에 닿지 못했어요. 주소·포트와 네트워크 연결을 확인하세요.": "Não foi possível alcançar o servidor. Verifique o endereço, a porta e a conexão de rede.",
 "서버에 로그인은 됐지만 Arkism이 설치돼 있지 않아요.": "O login no servidor funcionou, mas o Arkism não está instalado lá.",
 "서버의 Arkism이 오래돼서 이 연결 방식을 몰라요. 서버의 Arkism을 업데이트해 주세요.": "O Arkism do servidor é antigo demais e não reconhece este tipo de conexão. Atualize o Arkism no servidor.",
 "연결은 됐지만 서버의 Arkism을 열지 못했어요. 서버에서 Arkism이 켜져 있는지 확인하세요.": "Conectou, mas não foi possível abrir o Arkism do servidor. Verifique se o Arkism está em execução no servidor.",
