 "노드 설정": "Configurações do nó",
 "노드를 누르면 여기서 고쳐요. 출력 점을 끌어 다음 노드에 이어요. 앞 노드로 이으면 되돌아가는 선이 돼요. 선을 누르면 선 설정이 열려요. 휠로 확대·축소하고, 휠 클릭이나 스페이스를 누른 채 끌면 화면이 움직여요.": "Clique em um nó para editá-lo aqui. Arraste o ponto de saída para conectar ao próximo nó; ao conectar a um nó anterior, forma-se uma linha de retorno. Clique em uma linha para abrir as configurações dela. Use a roda para ampliar ou reduzir; clique com a roda e arraste, ou segure Espaço e arraste, para mover a tela.",
