 "개선안 만들기 → 기존 버전과 비교 → 검토·승인 → 실제 작업에 시험 적용 순서로 진행해요.": "Siga esta ordem: criar uma melhoria → comparar com a versão atual → revisar e aprovar → testar em trabalho real.",
 "저장소 주소를 넣으면 안에 있는 스킬을 보여 줘요. 받은 파일은 실행하지 않아요.": "Informe o endereço de um repositório para ver as skills dentro dele. Os arquivos baixados não são executados.",
 "에이전트가 일할 때 꺼내 쓰는 작업 방법이에요.": "São os modos de trabalho que os agentes usam quando estão trabalhando.",
 "앱·메일·웹·문서에 쓰는 색·글꼴·규칙 모음이에요. 하나를 고르면 오른쪽에서 자세히 볼 수 있어요.": "Conjuntos de cores, fontes e regras para apps, e-mail, web e documentos. Escolha um para ver os detalhes à direita.",
 "슬라이드 프롬프트": "Prompts de slides",
 "변수 값을 채우고 바로 만들거나, ComfyUI 워크플로우로 보내요.": "Preencha as variáveis e crie na hora, ou envie para um workflow do ComfyUI.",
 "발표·보고용 슬라이드 프롬프트와 만드는 스크립트를 모아 둬요. 카드를 고르면 오른쪽에서 고치고 바로 만들 수 있어요.": "Reúne prompts de slides para apresentações e relatórios, além dos scripts que os criam. Escolha um card para editar à direita e criar na hora.",
 "자주 쓰는 이미지 프롬프트를 예시 이미지와 함께 모아 둬요. 모델과 카테고리로 골라 보세요.": "Reúne seus prompts de imagem favoritos com imagens de exemplo. Filtre por modelo e categoria.",
 "플러그인은 스킬 + MCP + 명령을 한 번에 설치하는 묶음이에요.": "Um plugin é um pacote que instala skills, MCP e comandos de uma só vez.",
 "에이전트가 쓰는 외부 도구 서버예요. 플러그인은 스킬·MCP를 묶어서 한 번에 설치해요.": "Servidores de ferramentas externas usados pelos agentes. Plugins reúnem skills e MCP e instalam tudo de uma vez.",
 "이런 요청이 있었어요": "Estes pedidos chegaram",
