 "이미 있는 기억과 다른 내용이 들어왔어요. 어느 쪽이 맞는지 골라 주세요.": "Chegou um conteúdo diferente de uma memória que você já tem. Escolha qual dos dois está certo.",
 "확인해 주세요": "Confira, por favor",
