 "대화에서 관찰한 사용자 성향이에요. 지시나 실행 승인으로 쓰지 않아요.": "Tendências do usuário observadas nas conversas. Nunca são usadas como instrução nem como aprovação para executar.",
 "작업하면서 얻은 해석이에요. 사실이나 실행 승인으로 쓰지 않아요.": "Interpretações obtidas durante o trabalho. Nunca são usadas como fatos nem como aprovação para executar.",
 "정한 시각에 쓰이던 기억을 그대로 보여 줘요. 지금 지시로는 쓰지 않아요.": "Mostra exatamente as memórias que estavam em uso no horário escolhido. Não são usadas como instruções atuais.",
