 "OpenSSH(또는 Git for Windows)가 이 PC에 있어야 해요.": "Este PC precisa ter o OpenSSH (ou o Git for Windows).",
 "이름·모델·프롬프트를 적어 주세요. 제외할 것이나 스크립트는 오른쪽에서 더할 수 있어요. {변수}처럼 중괄호로 쓰면 변수가 돼요.": "Informe o nome, o modelo e o prompt. O que deve ficar de fora e os scripts podem ser adicionados à direita. Escreva entre chaves, como {variável}, para criar uma variável.",
 "AI로 이름 짓기": "Dar um nome com IA",
 "파일을 고르거나 이미지를 붙여 넣어요. 저장할 때 512KB 이하 WebP로 줄여요.": "Escolha um arquivo ou cole uma imagem. Ao salvar, ela é reduzida para WebP com no máximo 512KB.",
 "추가 설정": "Mais configurações",
 "비워 두면 모델 기본값으로 만들어요.": "Se deixar em branco, usaremos os padrões do modelo.",
