 "기본 정보": "Informações básicas",
 "갤러리 카드에 보이는 이름과 설명이에요. 제품과 목적이 같은 것끼리 묶여요.": "O nome e a descrição que aparecem no card da galeria. Os de mesmo produto e finalidade ficam agrupados.",
 "색과 글꼴": "Cores e fontes",
 "색은 \"이름 #값\"을 한 줄에 하나씩 적어요.": "Escreva as cores como \"nome #valor\", uma por linha.",
