 "다른 곳에서 수정됐으면 최신 내용을 확인한 뒤 다시 저장하세요.": "Se foi editado em outro lugar, confira a versão mais recente e salve de novo.",
 "영역 메뉴": "Menu da área",
 "연결 방법": "Como conectar",
 "Arkism 서버를 새 버전으로 올리면 디자인 시스템을 저장할 수 있어요.": "Atualize o servidor do Arkism para uma versão nova para poder salvar sistemas de design.",
