 "아직 없어요. 늘 알아야 하는 결정·스킬·문서를 넣어 두면, 부를 때마다 검색보다 먼저 들어가요.": "Ainda não há nada. Adicione decisões, skills ou documentos que ele deve sempre saber; eles entram antes da busca a cada chamada.",
 "전체=다 넣기 · 요약=줄여서 넣기 · 참조=제목만 넣고 필요할 때 읽기 · 고정=그 버전만, 최신=바뀌면 따라가기": "Completo = tudo · Resumo = versão curta · Referência = só o título, lido quando preciso · Fixa = só aquela versão, Mais recente = acompanha as mudanças",
 "나중에": "Depois",
 "설정됨": "Configurado",
 "토큰 파일이 깨졌거나 다른 사용자도 읽을 수 있게 열려 있어요. 다시 만들면 고쳐져요.": "O arquivo de token está danificado ou pode ser lido por outros usuários. Criar um novo resolve.",
 "모델 중계기": "Gateway de modelos",
 "중계기 토큰을 다시 만들까요? 에이전트 설정에 새 토큰을 넣어요.": "Criar um novo token do gateway? Ele será colocado nas configurações dos agentes.",
 "새 토큰을 만들고 에이전트 설정에 넣었어요. 중계기를 다시 켜면 예전 토큰은 막혀요.": "Criei um novo token e coloquei nas configurações dos agentes. O token antigo deixa de funcionar quando você reiniciar o gateway.",
 "새 토큰을 만들었어요. 에이전트 설정에는 못 넣었어요 — 진단에서 고치기를 눌러 주세요.": "Criei um novo token, mas não consegui colocá-lo nas configurações dos agentes — clique em Corrigir em Diagnóstico.",
 "토큰을 만들지 못했어요.": "Não foi possível criar o token.",
