 "route_skills가 고른 스킬과 판정기예요. 규칙은 판정 모델 없이 검색 1위를 고른 것이고, 확신 낮음은 판정기가 고르지 않은 것이에요.": "As skills que route_skills escolheu e o avaliador usado. Regras significa que o 1º resultado da busca foi escolhido sem modelo avaliador; pouca confiança significa que o avaliador não escolheu.",
