 "주제 요약": "Resumos de tópicos",
 "새로 들어온 기억이 이미 있는 기억과 비슷해요. AI 제안을 보고 저장할지, 합칠지, 건너뛸지 골라 주세요.": "As novas memórias parecem com outras que você já tem. Veja a sugestão da IA e escolha entre salvar, mesclar ou pular.",
 "비슷한 기억을 주제로 묶고 AI가 요약해요. 요약이 바뀌면 바로 쓰지 않고 먼저 확인을 받아요.": "Memórias parecidas são agrupadas em tópicos e resumidas pela IA. Se um resumo mudar, ele só é usado depois da sua aprovação.",
