 "아직 주제 요약이 없어요. 승인된 기억이 쌓이면 밤사이 제안돼요.": "Ainda não há resumos de tópicos. Eles são sugeridos durante a noite quando houver memórias aprovadas suficientes.",
 "요약을 불러오지 못했어요. 새로고침하면 다시 불러와요.": "Não foi possível carregar os resumos. Atualize para tentar de novo.",
 "여기에 표시할 요약이 없어요.": "Não há resumos para mostrar aqui.",
 "· 최대 개수에 닿아서 합치기 제안이 나올 수 있어요": "· Chegou ao limite, então podem aparecer rascunhos de mesclagem",
 "나에 대한 요약": "Resumo sobre mim",
 "바탕 기억이 바뀌거나 지워져 쓸 수 없어요. 다음 실행 때 다시 제안돼요.": "As memórias de origem mudaram ou foram apagadas, então ele não pode ser usado. Será sugerido de novo na próxima execução.",
 "아직 쓰는 요약은 없어요. 후보를 확인해 주세요.": "Ainda não há resumo em uso. Confira o rascunho.",
