 "주제를 고르세요": "Escolha um tópico",
 "비슷한 기억을 묶은 요약이에요. 사실이나 지시가 아니라 참고 자료로 쓰여요.": "Um resumo de memórias parecidas. É usado como referência, não como fato nem instrução.",
 "지금 요약": "Resumo atual",
 "묶인 기억": "Memórias agrupadas",
 "질문이 이 주제와 맞을 때": "Quando uma pergunta combina com este tópico",
 "모든 에이전트 · 참고 자료로": "Todos os agentes · como referência",
 "승인된 기억으로 AI가 새 주제를 묶었어요. 이 요약을 쓸까요?": "A IA agrupou memórias aprovadas em um novo tópico. Usar este resumo?",
 "비슷한 두 요약을 하나로 합치자는 후보예요. 합치면 두 요약은 이전 버전으로 남아요.": "Um rascunho que junta dois resumos parecidos. Se mesclar, os dois ficam como versões anteriores.",
 "AI가 요약을 고쳤어요. 이 후보로 바꿀까요?": "A IA corrigiu o resumo. Quer trocar por este rascunho?",
 "모아보기 · 나에 대한 요약": "Agrupar · Sobre mim",
 "승인하면 새 세션 시작 때 에이전트에게 참고 자료로 전달돼요(지시가 아님).": "Depois de aprovado, os agentes recebem isso como material de referência quando uma nova sessão começa (não é uma instrução).",
