 "이미지 프롬프트의 ‘ComfyUI에서 열기’가 여는 주소예요.": "O endereço que \"Abrir no ComfyUI\" abre a partir dos prompts de imagem.",
 "화면·정렬·분류 설정을 파일로 옮겨요.": "Transfere as configurações de tela, ordenação e categorias por um arquivo.",
 "‘유지’한 기억과 정리 설정을 옮겨요. 같은 계정에서만 가져올 수 있어요.": "Transfere as memórias marcadas como \"Manter\" e as configurações de limpeza. Só dá para importar na mesma conta.",
 "스킬 제안 초안과 숨긴 제안을 옮겨요. 같은 계정에서만 가져올 수 있고, 초안 본문이 들어 있어요.": "Transfere os rascunhos de sugestões de skills e as sugestões ocultas. Só dá para importar na mesma conta, e o arquivo contém o texto dos rascunhos.",
