 "비밀번호 로그인이 거부됐어요. 비밀번호를 확인하세요. 서버가 비밀번호 로그인을 막아 두었으면 SSH 키가 필요해요.": "O login com senha foi recusado. Verifique a senha. Se o servidor bloqueia login com senha, é preciso uma chave SSH.",
