 "서버의 Git·스킬 화면은 이 연결로 돼요. 에이전트의 기억 수집은 SSH 키가 있어야 서버로 가요.": "As telas de Git e Skills do servidor usam esta conexão. A coleta de memórias dos agentes só chega ao servidor com uma chave SSH.",
