 "SSH 키 또는 비밀번호로 접속해요. 비밀번호는 이 PC의 키체인에 저장해 다시 묻지 않고, 연결 끊기를 누르면 지금 연결된 서버의 비밀번호를 지워요.": "Conecta com uma chave SSH ou uma senha. A senha fica guardada no chaveiro deste PC para não ser pedida de novo, e Desconectar apaga a senha do servidor conectado no momento.",
