 "서버에 연결해 쓰는 동안에는 서버가 정한 폴더 위치를 써요.": "Enquanto você estiver conectado a um servidor, ele usa os locais de pasta definidos pelo servidor.",
 "아직 확인 안 됨": "ainda não confirmado",
 "임베딩을 바꿀까요?\n저장하면 기억을 모두 다시 색인해요. 기억이 많으면 시간이 걸려요.": "Trocar o embedding?\nAo salvar, todas as memórias serão reindexadas. Se houver muitas memórias, isso pode demorar.",
