 "회의 결과": "Resultado da reunião",
 "하위 실행": "Execução filha",
 "사람의 결정이 필요해요": "É preciso uma decisão de uma pessoa",
 "최신 실행을 다시 열어 주세요.": "Abra a execução mais recente novamente.",
 "중단을 요청했어요. 실제 종료 상태를 확인해 주세요.": "A parada foi solicitada. Confira o estado final real.",
 "결정을 보냈어요. 실행 상태를 다시 확인해요.": "A decisão foi enviada. Verificando o estado da execução de novo.",
 "보내지 못했어요. 상태가 바뀌었거나 권한이 없을 수 있어요. 다시 열어 확인해 주세요.": "Não foi possível enviar. O estado pode ter mudado ou pode faltar permissão. Abra de novo e confira.",
 "대화로 전달": "Entrega na conversa",
 "보냈는지 확인되지 않아 자동으로 다시 보내지 않아요. 원래 대화와 저장된 메시지 영수증을 먼저 확인해 주세요.": "Não foi confirmado se foi enviado, por isso não será reenviado automaticamente. Confira primeiro a conversa original e os recibos das mensagens salvas.",
 "권한이나 대화 상태를 확인해 주세요. 전달을 복구하려고 작업을 다시 실행하지 마세요.": "Verifique as permissões e o estado da conversa. Não execute a tarefa de novo para recuperar a entrega.",
 "아직 결론이 없어요.": "Ainda não há conclusão.",
 "전체 회의 기록": "Histórico completo da reunião",
 "전달 복구": "Recuperar entrega",
