 "전달 복구 방법": "Método de recuperação da entrega",
 "복구 방법 선택": "Escolha um método de recuperação",
 "미확인 부분부터 다시 보내기": "Reenviar a partir da parte não confirmada",
 "이미 받은 메시지 확인하기": "Confirmar uma mensagem já recebida",
 "다른 대화로 처음부터 보내기": "Enviar tudo desde o início para outra conversa",
 "원래 대화에서 미확인 부분이 전송되지 않았는지 확인해 주세요. 이미 받은 부분을 다시 보내면 중복될 수 있어요.": "Verifique se a parte não confirmada não foi enviada na conversa original. Reenviar uma parte já recebida pode duplicá-la.",
 "원래 대화에서 현재 미확인 부분을 받은 메시지의 ID를 입력해요. 확인 후 다음 부분부터 이어서 전달해요.": "Digite o ID da mensagem que recebeu a parte não confirmada na conversa original. Depois da confirmação, a entrega continua a partir da próxima parte.",
 "입력한 새 대화에 전체 결과를 처음부터 보내요. 기존 대화와 메시지 영수증은 복구 이력에 남아요.": "Envia o resultado completo, desde o início, para a nova conversa informada. A conversa anterior e os recibos das mensagens ficam no histórico de recuperação.",
 "원래 대화를 확인했고 미확인 부분을 다시 보내는 데 동의해요.": "Conferi a conversa original e concordo em reenviar a parte não confirmada.",
 "입력한 메시지가 현재 미확인 부분의 실제 수신 메시지임을 확인했어요.": "Confirmei que esta mensagem é a que realmente recebeu a parte não confirmada atual.",
 "새 목적지와 접근 권한을 확인했고 전체 결과를 보내는 데 동의해요.": "Conferi o novo destino e as permissões e concordo em enviar o resultado completo.",
 "사람 계정의 복구 권한이 필요해요. 원래 대화를 확인한 뒤 방법을 선택해 주세요.": "É preciso a permissão de recuperação de uma conta de pessoa. Confira a conversa original e depois escolha um método.",
 "복구 내용 확인": "Confirmar detalhes da recuperação",
 "확인한 내용으로 복구 요청": "Solicitar a recuperação confirmada",
