 "지우는 이유 (선택)": "Motivo para apagar (opcional)",
 "메모를 남기려면 이유를 하나 골라 주세요.": "Para deixar uma nota, escolha um motivo.",
 "합치기 제안을 불러오지 못했어요. 새로고침하면 다시 불러와요.": "Não foi possível carregar as sugestões de união. Atualize para tentar de novo.",
