 "합치기 제안": "Sugestões de união",
 "합치기 제안 · AI 제안": "Sugestão de união · sugestão da IA",
 "지운 기억이에요. 에이전트는 쓰지 않아요. 되살리면 지우기 전처럼 다시 써요.": "Esta memória foi apagada. Os agentes não a usam. Se você restaurar, eles voltam a usá-la como antes.",
 "지웠어요. 「지운 기억」에서 언제든 되살릴 수 있어요.": "Apagada. Você pode restaurá-la quando quiser em「Memórias apagadas」.",
 "예전 방식으로 저장돼 사람이 승인한 기록이 남지 않은 기억이에요. 할 일은 없고, 내용도 바꾸지 않아요.": "Estas foram salvas do jeito antigo, então não há registro de aprovação por uma pessoa. Não há nada a fazer, e o conteúdo não muda.",
 "지운 기억": "Memórias apagadas",
 "지운 기억은 에이전트가 쓰지 않아요. 되살리면 다시 써요.": "Os agentes não usam memórias apagadas. Se você restaurar uma, eles voltam a usá-la.",
 "아직 기억이 없어요. AI와 대화하면 기억할 만한 내용이 「확인해 주세요」에 올라와요. 직접 적어 둘 수도 있어요.": "Ainda não há memórias. Quando você conversa com a IA, o que vale a pena lembrar aparece em「Para conferir」. Você também pode escrever uma por conta própria.",
