 "고급 · 요청 헤더 추가 (사내 게이트웨이 인증)": "Avançado · Adicionar cabeçalhos de requisição (autenticação do gateway da empresa)",
 "값은 키처럼 서버에만 저장돼요 · 화면엔 이름만 보여요": "Os valores ficam guardados só no servidor, como as chaves · na tela aparecem só os nomes",
 "헤더 이름은 영문·숫자·-로 쓰고 값도 넣어 주세요. 키는 API 키 칸에 넣어요.": "Use letras, números e - no nome do cabeçalho e informe também o valor. A chave vai no campo Chave de API.",
 "개발 빌드": "Build de desenvolvimento",
 "토큰은 Arkism에 암호화해 저장하고, 화면에는 끝 4자리만 보여요. 디스코드 개발자 포털에서 봇을 만들고 Message Content Intent를 켠 뒤 토큰을 넣어 주세요.": "O token é guardado criptografado no Arkism e só os últimos 4 caracteres aparecem na tela. Crie um bot no portal de desenvolvedores do Discord, ative o Message Content Intent e cole o token.",
 "토큰은 Arkism에 저장하고, 화면에는 끝 4자리만 보여요. @BotFather로 만든 봇을 그룹이나 DM에 먼저 추가해 두세요.": "O token é guardado no Arkism e só os últimos 4 caracteres aparecem na tela. Primeiro adicione a um grupo ou DM o bot que você criou com o @BotFather.",
 "웹훅 주소는 Arkism에 저장하고, 화면에는 끝 4자리만 보여요. 슬랙의 Incoming Webhooks에서 만들어요.": "O endereço do webhook é guardado no Arkism e só os últimos 4 caracteres aparecem na tela. Crie um em Incoming Webhooks do Slack.",
 "바꾸려면 팀·전문가 상세의 채널 연결에서 해요.": "Para mudar, use a conexão de canal nos detalhes da equipe ou do especialista.",
 "아직 답이 없어요. 잠시 뒤 다시 확인해 주세요.": "Ainda não há resposta. Confira de novo daqui a pouco.",
 "10분 안에 로그인이 끝나지 않았어요. 다시 눌러 주세요.": "O login não terminou em 10 minutos. Toque de novo.",
 "로그인 창을 열지 못했어요. 터미널에서 아래 명령을 실행해 주세요.": "Não foi possível abrir a janela de login. Execute o comando abaixo em um terminal.",
 "로그인은 됐지만 계정을 넣지 못했어요. 다시 눌러 주세요.": "O login deu certo, mas não foi possível adicionar a conta. Toque de novo.",
 "로그인 버튼을 누르면 로그인 창이 열려요. 브라우저에서 로그인을 마치면 여기 바로 보여요.": "Ao tocar em Entrar, a janela de login abre. Quando você terminar no navegador, aparece aqui na hora.",
 "로그인 창을 열었어요": "A janela de login foi aberta",
 "브라우저에서 로그인을 마치면 여기서 바로 알려 줘요. 창을 닫지 마세요.": "Quando você terminar o login no navegador, avisamos aqui. Não feche esta janela.",
 "이제 이 계정으로 AI를 쓸 수 있어요.": "Agora você pode usar a IA com esta conta.",
 "로그인하지 못했어요. 다시 눌러 주세요.": "Não foi possível entrar. Toque de novo.",
