 "사람의 사정과 기분을 얼마나 살필지": "Quanto considerar a situação e os sentimentos das pessoas",
 "질문에 답하는 방식": "Como as perguntas são respondidas",
 "에이전트가 기억을 모아 답할 때(reflect) 따를 목표와 태도예요.": "O objetivo e a postura que os agentes seguem ao reunir memórias para responder (reflect).",
