 "하루마다": "Todo dia",
 "일주일마다": "Toda semana",
 "자동 정리 제안": "Sugestões de organização automática",
 "승인한 기억이 쌓이면 서버 모델이 읽고 관찰·원인·이름 정리를 제안해요. 제안은 내가 승인해야 쓰여요.": "Quando as memórias aprovadas se acumulam, um modelo do servidor as lê e sugere observações, causas e organização de nomes. As sugestões só são usadas depois que você aprovar.",
 "자동으로 정리 제안 만들기": "Criar sugestões de organização automaticamente",
 "처음에는 꺼져 있어요. 켜면 모델 사용량(예산)을 써요.": "Começa desligado. Ao ligar, usa o uso de modelo (orçamento).",
 "켜져 있어요. 정리할 때마다 서버 모델을 불러 모델 예산을 써요.": "Ligado. A cada organização, um modelo do servidor é chamado e gasta o orçamento de modelo.",
 "몇 개 승인마다": "A cada quantas aprovações",
 "얼마나 자주": "Com que frequência",
 "자세히 · 언제 만들지": "Detalhes · quando criar",
 "승인한 기억이 이만큼 쌓이면 정리를 시작해요 (1~1000)": "A organização começa quando essa quantidade de memórias aprovadas se acumula (1~1000)",
 "쌓인 게 적어도 이 간격이 지나면 정리해요": "A organização também roda depois desse intervalo, mesmo que tenham se acumulado poucas",
 "기본 템플릿": "Modelo padrão",
 "서버에 준비된 기본 템플릿의 규칙과 정리 틀을 이 공간에 가져와요. 설정을 한 번도 저장하지 않은 공간에서만 돼요. 가져온 것은 후보로 들어가요.": "Traz para este espaço as regras e a estrutura de organização do modelo padrão do servidor. Só funciona em um espaço cujas configurações nunca foram salvas. O que for trazido entra como candidato.",
 "기본 템플릿 가져오기": "Importar modelo padrão",
 "서버의 기본 템플릿을 이 공간에 가져올까요? 바로 쓰이지 않고 '확인해 주세요'에 후보로 들어가요.": "Importar o modelo padrão do servidor para este espaço? Nada é usado de imediato; tudo entra como candidato em 'Precisa de confirmação'.",
 "서버에 기본 템플릿이 없어요.": "O servidor não tem um modelo padrão.",
 "이미 설정을 저장한 공간이라 템플릿을 가져올 수 없어요.": "Este espaço já tem configurações salvas, então não é possível importar o modelo.",
 "템플릿은 사람 계정만 가져올 수 있어요.": "Só contas de pessoa podem importar o modelo.",
 "템플릿이 있어요": "Há um modelo em uso",
 "이 공간은 설정을 저장한 적이 있어 가져올 수 없어요.": "Este espaço já teve configurações salvas, então não é possível importar.",
 "새 공간이라 가져올 수 있어요.": "Este é um espaço novo, então é possível importar.",
 "이 공간": "Este espaço",
