 "값 아래의 작은 글은 그 값이 어디서 왔는지예요: 이 공간에서 정함 · 템플릿에서 옴 · 기본값. ‘기본값으로’를 누르면 이 공간의 값을 지우고 물려받아요.": "O texto pequeno abaixo de cada valor mostra de onde ele vem: Definido neste espaço · Veio do modelo · Padrão. Ao tocar em ‘Restaurar padrão’, o valor deste espaço é apagado e passa a ser herdado.",
 "자세히 · 모두 물려받기": "Detalhes · herdar tudo",
 "이 공간에서 정한 동작 설정을 모두 지워요. 이름·메모는 남아요.": "Apaga todas as configurações de comportamento definidas neste espaço. O nome e as anotações permanecem.",
 "에이전트 계정이라 보기만 할 수 있어요. 바꾸려면 사람 계정으로 로그인해 주세요.": "Esta é uma conta de agente, então você só pode visualizar. Para fazer alterações, entre com uma conta de pessoa.",
 "이 계정에는 공간 설정을 바꿀 권한이 없어요. 서버 관리자에게 공간 설정 권한을 받아 주세요.": "Esta conta não tem permissão para alterar as configurações do espaço. Peça essa permissão ao administrador do servidor.",
 "자세하게": "Detalhado",
 "시험해 보기 (미리 보기)": "Testar (prévia)",
 "앱에서 바로 돌려 본 미리 보기라 서버 결과와 드물게 다를 수 있어요. 저장할 때 서버가 다시 검사해요.": "Esta é uma prévia executada direto no app, então em raros casos pode ser diferente do resultado do servidor. O servidor confere de novo quando você salva.",
 "낱말로 찾기": "Buscar por palavras",
