 "이 부분에서 만든 기억 후보가 없어요.": "Nenhuma sugestão de memória veio desta parte.",
 "이 자료로 만든 기억 후보 보기": "Ver as sugestões de memória deste material",
 "검색에 쓰는 부분과 올린 버전이에요. 내용은 사람에게만 보여요.": "As partes usadas na busca e as versões enviadas. O conteúdo só aparece para pessoas.",
 "파일에서 읽은 부분과 그 부분에서 나온 기억 후보예요. 후보는 '확인해 주세요'에서 승인해야 쓰여요.": "As partes lidas do arquivo e as sugestões de memória que saíram delas. Uma sugestão só é usada depois que você a aprova em 'Confira por favor'.",
 "부분이 없어요.": "Não há partes.",
