 "AI가 쓴 요약 초안이에요. 승인하기 전에는 쓰이지 않아요.": "Este é um rascunho de resumo escrito pela IA. Ele não é usado até você aprovar.",
 "근거 기억이 지워져서 내용을 가렸어요. 버리고 새 초안을 만들어 주세요.": "Uma memória citada foi apagada, então o conteúdo foi ocultado. Descarte este rascunho e crie um novo.",
 "요약을 승인했어요.": "Resumo aprovado.",
 "근거 기억이 그사이 바뀌어서 이 초안은 승인할 수 없어요. 버리고 새 초안을 만들어 주세요.": "As memórias citadas mudaram nesse meio tempo, então este rascunho não pode ser aprovado. Descarte-o e crie um novo.",
