 "승인과 거절은 사람만 할 수 있어요.": "Só uma pessoa pode aprovar ou recusar.",
 "이 제안을 거절할까요?\n제안한 규칙을 지워요.": "Quer recusar esta sugestão?\nA regra sugerida será apagada.",
 "제안을 거절했어요.": "Você recusou a sugestão.",
