 "예: 이 팀이 왜 그렇게 정했는지를 남겨요.": "Ex.: Guardar por que esta equipe decidiu as coisas do jeito que decidiu.",
 "무엇을 기억으로 남길지 한두 문장으로 알려 줘요. 2000자까지.": "Diga em uma ou duas frases o que deve virar memória. Até 2000 caracteres.",
 "긴 글을 이 글자 수로 나눠 읽어요 (500~12000). 비우면 물려받아요.": "Textos longos são lidos em partes com este número de caracteres (500~12000). Deixe vazio para herdar.",
 "원인과 결과도 후보로": "Causas e efeitos como candidatos",
 "한 일이 다른 일의 원인이면 그 연결도 후보로 만들어요.": "Quando algo que aconteceu causou outra coisa, essa ligação também vira candidato.",
 "기억을 쓰는 언어": "Idioma das memórias",
 "후보를 어떤 언어로 적을지예요. ‘말한 언어 그대로’는 내가 쓴 말을 따라요.": "O idioma em que os candidatos são escritos. ‘Idioma como falado’ segue as palavras que você usou.",
 "기준 시간대": "Fuso horário de referência",
 "‘어제’·‘지난주’ 같은 말을 날짜로 바꿀 때 쓰는 시간대예요.": "Fuso horário usado para transformar palavras como ‘ontem’ ou ‘semana passada’ em datas.",
 "작업 상태를 후보로": "Estado do trabalho como candidatos",
