 "라벨": "Rótulos",
 "아직 없어요. 예: 우선순위(높음, 보통, 낮음)처럼 정해 두면 그 값으로만 붙여요.": "Ainda não há nenhum. Se você definir, por exemplo, prioridade (alta, normal, baixa), só esses valores serão usados.",
