 "결정할 때까지 빼기": "Deixar de fora até decidir",
 "세션 원문에서도 찾기": "Buscar também no texto original das sessões",
 "저장된 대화 원문도 찾는 길에 넣어요. 처음에는 꺼져 있어요.": "O texto original das conversas salvas também entra na busca. Desligado no início.",
 "찾는 방법별 무게": "Peso por método de busca",
 "1이 보통이에요. 크게 하면 그 방법으로 찾은 기억이 앞에 와요 (0.25~8).": "1 é o normal. Quanto maior, mais à frente ficam as memórias achadas por esse método (0,25~8).",
