 "낱말만 우연히 맞고 뜻이 먼 기억을 빼요. 처음에는 켜져 있어요.": "Tira memórias em que só as palavras coincidem por acaso e o sentido é distante. Ligado no início.",
 "정정을 기다리는 기억": "Memórias aguardando correção",
 "고쳐 달라는 후보가 있는 기억을 어떻게 보여 줄지예요.": "Como mostrar memórias que têm um candidato de correção pendente.",
 "승인 전 후보도 보여 주기": "Mostrar também candidatos não aprovados",
 "아직 승인하지 않은 후보를 ‘승인 전’ 표시와 함께 몇 개 보여 줘요. 확정된 기억처럼 쓰이지 않아요.": "Mostra alguns candidatos ainda não aprovados, com a marca ‘não aprovado’. Eles não são usados como memórias confirmadas.",
