 "더 보낼 헤더 (한 줄에 하나, 이름: 값)": "Cabeçalhos extras (um por linha, nome: valor)",
 "주소에 붙일 쿼리 (한 줄에 하나, 이름=값)": "Query para adicionar ao endereço (uma por linha, nome=valor)",
 "헤더·쿼리 값은 봉인해 저장해서 다시 보여 주지 않아요. 비워 두면 지금 값을 그대로 둬요. 주소의 도메인을 바꾸면 저장한 헤더·쿼리는 지워지니 다시 넣어 주세요.": "Os valores de cabeçalhos e queries são guardados em segredo e não aparecem de novo. Se deixar em branco, os valores atuais continuam. Se você mudar o domínio do endereço, os cabeçalhos e queries salvos serão apagados, então informe-os novamente.",
