 "이 서버는 직접 정한 주제를 지원하지 않아요.": "Este servidor não oferece suporte a tópicos próprios.",
 "아직 직접 정한 주제가 없어요. 「새 주제 만들기」로 궁금한 것을 적으면 AI가 승인된 기억으로 요약 초안을 써요.": "Você ainda não tem tópicos próprios. Escreva uma dúvida em「Criar novo tópico」e a IA escreve um rascunho de resumo com as memórias aprovadas.",
 "궁금한 것을 질문으로 적어 두면, AI가 승인된 기억만 읽고 요약 초안을 써요. 초안은 사람이 승인해야 쓰여요.": "Escreva como pergunta o que você quer saber, e a IA lê só as memórias aprovadas e escreve um rascunho de resumo. O rascunho só é usado depois que uma pessoa aprovar.",
 "AI가 새 초안을 썼어요. 확인해 주세요 › AI 정리에서 승인하거나 버려 주세요.": "A IA escreveu um novo rascunho. Aprove ou descarte em Confira › Resumos da IA.",
