 "요약을 비웠어요.": "Resumo limpo.",
 "글은 그대로예요.": "O texto continua igual.",
 "직접 정한 주제 · 고치기": "Meus tópicos · Editar",
 "직접 정한 주제 · 새로 만들기": "Meus tópicos · Novo",
 "질문을 적으면 AI가 승인된 기억만 읽고 요약 초안을 써요. 초안은 사람이 승인해야 쓰여요.": "Escreva uma pergunta e a IA lê só as memórias aprovadas e escreve um rascunho de resumo. O rascunho só é usado depois que uma pessoa aprovar.",
 "예: 배포 전에 확인할 것": "Ex.: o que conferir antes de publicar",
