 "기억 정리가 끝나면 다시 만들기": "Refazer quando os resumos de memória terminarem",
 "일정 (분 시 일 월 요일, UTC)": "Agenda (minuto hora dia mês dia da semana, UTC)",
 "일정 미리보기": "Prévia da agenda",
 "전체 다시 쓰기 일정 (UTC)": "Agenda de reescrita completa (UTC)",
 "일정을 적으면 다음 실행 시각을 보여 줘요.": "Digite uma agenda para ver os próximos horários de execução.",
 "다음 실행 (이 PC 시각)": "Próximas execuções (horário deste PC)",
 "일정 형식이 맞지 않아요. 분 시 일 월 요일, 다섯 칸으로 적어 주세요.": "O formato da agenda não está certo. Escreva em cinco campos: minuto hora dia mês dia da semana.",
 "제목과 질문을 적어 주세요.": "Escreva um título e uma pergunta.",
 "주제를 고쳤어요.": "Tópico atualizado.",
 "주제를 만들었어요. 「다시 만들기」를 누르거나 정한 때가 되면 AI가 초안을 써요.": "Tópico criado. A IA escreve um rascunho quando você tocar em「Refazer」ou chegar a hora definida.",
 "입력한 값을 확인해 주세요. 일정은 다섯 칸, 최소 간격은 6h처럼 적어요.": "Confira o que você digitou. A agenda tem cinco campos, e o intervalo mínimo deve ser escrito como 6h.",
 "이 계정은 주제를 만들거나 고칠 수 없어요.": "Esta conta não pode criar nem editar tópicos.",
 "정리를 불러오는 중…": "Carregando resumos…",
 "정리를 불러오지 못했어요. 새로고침하면 다시 불러와요.": "Não foi possível carregar os resumos. Atualize a página para tentar de novo.",
 "여기에 표시할 정리가 없어요. 「지금 정리하기」로 AI에게 정리를 맡길 수 있어요.": "Não há resumos para mostrar aqui. Use「Resumir agora」para pedir à IA que resuma.",
 "AI가 승인된 기억 여러 개를 읽고 쓴 정리예요. 승인된 것만 기억과 함께 쓰여요.": "Resumos que a IA escreveu depois de ler várias memórias aprovadas. Só os aprovados são usados junto com as memórias.",
 "이 정리를 지울까요? 이력은 남고, 다음 정리 때 다시 제안될 수 있어요.": "Excluir este resumo? O histórico continua, e ele pode ser sugerido de novo no próximo resumo.",
 "정리를 지웠어요.": "Resumo excluído.",
 "그사이 정리가 바뀌었어요. 새로 불러왔어요.": "O resumo mudou nesse meio tempo. Carreguei de novo.",
 "이 계정은 정리를 지울 수 없어요.": "Esta conta não pode excluir resumos.",
 "기억 정리 · 지금 실행": "Resumos de memória · Executar agora",
 "AI가 승인된 기억을 다시 읽고 새 정리나 고친 정리를 제안해요. 제안은 확인해 주세요 › AI 정리에서 승인해야 쓰여요.": "A IA relê as memórias aprovadas e sugere resumos novos ou atualizados. As sugestões só são usadas depois de aprovadas em Confira › Resumos da IA.",
 "살펴보는 중…": "Analisando…",
 "1. 살펴보기": "1. Analisar",
 "2. 정리": "2. Resumir",
